using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;using AutosurBuscador;
class UpdateTests {
 static void Reject(string zip){bool rejected=false;try{UpdateManager.ValidatePackage(zip);}catch{rejected=true;}if(!rejected)throw new Exception("Se aceptó un paquete inválido");}
 static WebClient Web(bool asset){return (WebClient)typeof(UpdateManager).GetMethod("Web",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{asset});}
 static void Main(string[] args){string dir=Path.Combine(Path.GetTempPath(),"AutosurUpdates_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
 string valid=Path.Combine(dir,"valid.zip");using(var z=ZipFile.Open(valid,ZipArchiveMode.Create)){z.CreateEntry(UpdateManager.PackageFolder+"/Instalar.ps1");z.CreateEntry(UpdateManager.PackageFolder+"/app.cs");}UpdateManager.ValidatePackage(valid);Console.WriteLine("OK paquete de la aplicación");
 string invalid=Path.Combine(dir,"invalid.zip");using(var z=ZipFile.Open(invalid,ZipArchiveMode.Create)){z.CreateEntry(UpdateManager.PackageFolder+"/Instalar.ps1");z.CreateEntry(UpdateManager.PackageFolder+"/../escape.ps1");}Reject(invalid);Console.WriteLine("OK rechaza rutas fuera del paquete");
 string wrong=Path.Combine(dir,"wrong.zip");using(var z=ZipFile.Open(wrong,ZipArchiveMode.Create))z.CreateEntry("otra-app/Instalar.ps1");Reject(wrong);Console.WriteLine("OK rechaza otra aplicación");
 foreach(string name in new[]{"clientes.dat","VEHICULOS.DAT","datos/otro.dat"}){string zip=Path.Combine(dir,Guid.NewGuid().ToString("N")+".zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){z.CreateEntry(UpdateManager.PackageFolder+"/Instalar.ps1");z.CreateEntry(UpdateManager.PackageFolder+"/"+name);}Reject(zip);}Console.WriteLine("OK rechaza cualquier DAT en actualizaciones");
 foreach(bool asset in new[]{false,true})using(var w=Web(asset)){if(!String.IsNullOrEmpty(w.Headers[HttpRequestHeader.Authorization]))throw new Exception("Se envían credenciales");}Console.WriteLine("OK consultas y descargas sin Authorization");
 var spoof=new Dictionary<string,object>{{"name",UpdateManager.PackageName},{"browser_download_url","https://github.com/otra/app/releases/download/v1/otro.zip"}};bool rejected=false;try{UpdateManager.DownloadPackage(spoof,Path.Combine(dir,"spoof.zip"));}catch{rejected=true;}if(!rejected)throw new Exception("Se aceptó otro repositorio");Console.WriteLine("OK descarga limitada al repositorio Autosur");
 string credential=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),UpdateManager.AppName,"datos","github-access.bin");byte[] old=File.Exists(credential)?File.ReadAllBytes(credential):null;try{Directory.CreateDirectory(Path.GetDirectoryName(credential));File.WriteAllText(credential,"OBSOLETE_SYNTHETIC_TEST_DATA");UpdateManager.RemoveLegacyAccess();if(File.Exists(credential))throw new Exception("No se retiró el acceso antiguo");Console.WriteLine("OK retira acceso antiguo sin leerlo");}finally{if(old!=null)File.WriteAllBytes(credential,old);else if(File.Exists(credential))File.Delete(credential);}
 if(args.Contains("--public-live")){
 var latest=UpdateManager.PublishedRelease();if(!latest.ContainsKey("tag_name"))throw new Exception("Falta release pública");Console.WriteLine("OK consulta pública real sin cuenta ni token: "+latest["tag_name"]);
 object[] releases;using(var w=Web(false))releases=new JavaScriptSerializer().Deserialize<object[]>(w.DownloadString("https://api.github.com/repos/"+UpdateManager.Repository+"/releases?per_page=100"));
 int count=0;foreach(var item in releases){var release=(Dictionary<string,object>)item;foreach(var entry in (object[])release["assets"]){var asset=(Dictionary<string,object>)entry;if(Convert.ToString(asset["name"])!=UpdateManager.PackageName)continue;string path=Path.Combine(dir,"published-"+count+".zip");UpdateManager.DownloadPackage(asset,path);count++;Console.WriteLine("OK descarga pública e integridad; paquete sin DAT: "+release["tag_name"]);}}
 if(count==0)throw new Exception("No se pudo validar ningún paquete publicado");Console.WriteLine("OK auditados "+count+" paquetes publicados sin credenciales");
 }
 }finally{Directory.Delete(dir,true);}Console.WriteLine("Pruebas de actualización aprobadas.");}
}
